mapper.select:
SELECT RSV_NO AS RSV_NO, CO_CD AS CO_CD, USER_ID AS USER_ID, (SELECT NAME FROM TB_CM06M01 WHERE ID = TB_PM60M01.USER_ID) AS USER_NM, TRIP_DIV AS TRIP_DIV, FN_CM05M01_CD_TO_NM(TRIP_DIV) AS TRIP_DIV_NM, TRIP_TYPE_CDS AS TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(TRIP_TYPE_CDS) AS TRIP_TYPE_CDS_NM, TRIP_COND_CD AS TRIP_COND_CD, FN_CM05M01_CD_TO_NM(TRIP_COND_CD) AS TRIP_COND_CD_NM, RSV_STS_CD AS RSV_STS_CD, FN_CM05M01_CD_TO_NM(RSV_STS_CD) AS RSV_STS_CD_NM, TRIP_PLACE AS TRIP_PLACE, TRIP_ST_DTM AS TRIP_ST_DTM, TRIP_ED_DTM AS TRIP_ED_DTM, SUBSTR(TRIP_ST_DTM, 1, 10) AS TRIP_ST_DTM_DISP, SUBSTR(TRIP_ED_DTM, 1, 10) AS TRIP_ED_DTM_DISP, NIGHT_CNT AS NIGHT_CNT, DAY_CNT AS DAY_CNT, ETC AS ETC, TRIP_REQ_NO AS TRIP_REQ_NO, CREAT_ID AS CREAT_ID, CREAT_DTTM AS CREAT_DTTM, UDT_ID AS UDT_ID, UDT_DTTM AS UDT_DTTM FROM TB_PM60M01 WHERE CO_CD = 'GUN'
AND SUBSTR(TRIP_ST_DTM, 1, 8) <= #{monthEdDt} AND SUBSTR(TRIP_ED_DTM, 1, 8) >= #{monthStDt}
ORDER BY USER_ID ASC, TRIP_ST_DTM ASC

SELECT M.TRIP_REQ_NO AS TRIP_REQ_NO, D.USER_ID AS USER_ID, NVL(( SELECT D2.TRIP_ST_DTM FROM TB_PM52D02 D2 INNER JOIN TB_PM52M01 R ON R.TRIP_RPT_NO = D2.TRIP_RPT_NO WHERE R.TRIP_REQ_NO = M.TRIP_REQ_NO AND D2.USER_ID = D.USER_ID AND ROWNUM = 1 ), D.TRIP_ST_DTM) AS TRIP_ST_DTM, NVL(( SELECT D2.TRIP_ED_DTM FROM TB_PM52D02 D2 INNER JOIN TB_PM52M01 R ON R.TRIP_RPT_NO = D2.TRIP_RPT_NO WHERE R.TRIP_REQ_NO = M.TRIP_REQ_NO AND D2.USER_ID = D.USER_ID AND ROWNUM = 1 ), D.TRIP_ED_DTM) AS TRIP_ED_DTM, M.TRIP_PLACE AS TRIP_PLACE, M.CLNT_PJT AS CLNT_PJT, FN_CM05M01_CD_TO_NM(M.CLNT_PJT) AS CLNT_PJT_NM, M.TRIP_TYPE_CDS AS TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(M.TRIP_TYPE_CDS) AS TRIP_TYPE_CDS_NM FROM TB_PM51D01 D INNER JOIN TB_PM51M01 M ON M.TRIP_REQ_NO = D.TRIP_REQ_NO WHERE D.USER_ID IN (SELECT ID FROM TB_CM06M01 WHERE DEPT_ID = 'GUN6010' AND USE_YN = 'Y')
AND SUBSTR( NVL(( SELECT D2.TRIP_ST_DTM FROM TB_PM52D02 D2 INNER JOIN TB_PM52M01 R ON R.TRIP_RPT_NO = D2.TRIP_RPT_NO WHERE R.TRIP_REQ_NO = M.TRIP_REQ_NO AND D2.USER_ID = D.USER_ID AND ROWNUM = 1 ), D.TRIP_ST_DTM), 1, 8) <= #{monthEdDt} AND SUBSTR( NVL(( SELECT D2.TRIP_ED_DTM FROM TB_PM52D02 D2 INNER JOIN TB_PM52M01 R ON R.TRIP_RPT_NO = D2.TRIP_RPT_NO WHERE R.TRIP_REQ_NO = M.TRIP_REQ_NO AND D2.USER_ID = D.USER_ID AND ROWNUM = 1 ), D.TRIP_ED_DTM), 1, 8) >= #{monthStDt}
ORDER BY D.USER_ID ASC, D.TRIP_ST_DTM ASC

SELECT WORK_RPT_ID AS USER_ID, TO_CHAR(WORK_RPT_DT, 'YYYYMMDD') AS WORK_RPT_DT, WORK_RPT_S AS WORK_RPT_S, FN_CM05M01_CD_TO_NM(WORK_RPT_S) AS WORK_RPT_S_NM, WORK_RPT_RMK AS REMARK FROM TB_PM01M01 WHERE WORK_RPT_S LIKE '%9901' AND WORK_RPT_ID IN (SELECT ID FROM TB_CM06M01 WHERE DEPT_ID = 'GUN6010' AND USE_YN = 'Y')
AND TO_CHAR(WORK_RPT_DT, 'YYYYMMDD') BETWEEN #{monthStDt} AND #{monthEdDt}
ORDER BY WORK_RPT_ID ASC, WORK_RPT_DT ASC

SELECT
	'예약' AS DOC_TYPE,
	RSV_NO AS DOC_NO,
	TRIP_ST_DTM AS TRIP_ST_DTM,
	TRIP_ED_DTM AS TRIP_ED_DTM,
	TRIP_PLACE AS TRIP_PLACE,
	FN_CM05M01_CD_TO_NM(TRIP_TYPE_CDS) AS TRIP_TYPE_NM
FROM TB_PM60M01
WHERE USER_ID = #{userId}

	AND RSV_NO != #{rsvNo}

AND SUBSTR(TRIP_ST_DTM, 1, 8) <= #{tripEdDate}
AND SUBSTR(TRIP_ED_DTM, 1, 8) >= #{tripStDate}

SELECT RSV_NO AS RSV_NO, CO_CD AS CO_CD, VNDR_NM AS VNDR_NM, WORK_DT AS WORK_DT, WORK_HOUR AS WORK_HOUR, ETC AS ETC, CREAT_ID AS CREAT_ID, CREAT_DTTM AS CREAT_DTTM, UDT_ID AS UDT_ID, UDT_DTTM AS UDT_DTTM FROM TB_PM60M02 WHERE CO_CD = 'GUN'
AND WORK_DT >= #{monthStDt} AND WORK_DT <= #{monthEdDt}
ORDER BY WORK_DT ASC, VNDR_NM ASC
